import { useState, type CSSProperties, type ReactNode } from 'react';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './shell.css';

type Props = { workspace: ReactNode; inspector: ReactNode; section: string; onNavigate: (section: string) => void; inspectorWidth: number; onInspectorWidthChange: (width: number) => void };
export function ApplicationShell({workspace, inspector, section, onNavigate, inspectorWidth, onInspectorWidthChange}: Props) {
  const [showNavigation, setShowNavigation] = useState(false);
  const [showInspector, setShowInspector] = useState(false);
  const width = Math.max(240, Math.min(480, inspectorWidth));
  return <div className="kui-layout application" style={{'--inspector-width': width + 'px'} as CSSProperties}>
    <a className="skip-link" href="#workspace">Skip to workspace</a>
    <Toolbar>
      <strong>Workspace</strong>
      <button className="phone-control" aria-expanded={showNavigation} aria-controls="navigation" onClick={() => setShowNavigation(!showNavigation)}>Navigation</button>
      <button className="phone-control" aria-expanded={showInspector} aria-controls="inspector" onClick={() => setShowInspector(!showInspector)}>Inspector</button>
    </Toolbar>
    <div className="application-panes">
      <nav id="navigation" aria-label="Workspace navigation" className={'kui-sidebar navigation ' + (showNavigation ? 'phone-open' : '')}>
        <section className="kui-sidebar-section"><MenuHeader>Workspace</MenuHeader>
          {['Overview', 'Projects'].map(name => <MenuItem key={name} aria-current={section === name ? 'page' : undefined} onClick={() => {onNavigate(name); setShowNavigation(false);}}>{name}</MenuItem>)}
        </section>
        <section className="kui-sidebar-section"><MenuHeader>Organization</MenuHeader><MenuItem onClick={() => onNavigate('Members')}>Members</MenuItem></section>
      </nav>
      <main id="workspace" tabIndex={-1} aria-label="Workspace" className="workspace">{workspace}</main>
      <aside id="inspector" aria-label="Inspector" className={'inspector ' + (showInspector ? 'phone-open' : '')}>
        <div className="inspector-adjustment">
          <label htmlFor="inspector-width">Inspector width</label>
          <input id="inspector-width" type="range" min={240} max={480} step={8} value={width} onChange={event => onInspectorWidthChange(Number(event.target.value))}/>
        </div>
        <div className="inspector-content">{inspector}</div>
      </aside>
    </div>
  </div>;
}
// The application supplies inspectorWidth and persists it in its own preferences store.
// No ResizableRegion is mounted: the named native range is the controlled keyboard
// and pointer adjustment, so this composition owns no separator wiring or disposer.

