.application { block-size: 100dvh; display: flex; flex-direction: column; overflow: hidden; }
.application-panes { display: grid; grid-template-columns: 15rem minmax(0,1fr) var(--inspector-width); flex: 1; min-block-size: 0; }
.navigation, .workspace, .inspector { min-inline-size: 0; min-block-size: 0; }
.navigation, .workspace { overflow: auto; overscroll-behavior: contain; }
.inspector { display: flex; flex-direction: column; border-inline-start: 1px solid currentColor; }
.inspector-adjustment { display: grid; }
.inspector-content { overflow: auto; min-block-size: 0; flex: 1; overscroll-behavior: contain; }
.phone-control { display: none; }
:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.skip-link { position: absolute; transform: translateY(-150%); }
.skip-link:focus { transform: none; z-index: 10; background: Canvas; color: CanvasText; }
@media (max-width: 48rem) {
  .phone-control { display: inline-block; min-block-size: 44px; }
  .application-panes { display: flex; flex-direction: column; overflow: auto; }
  .navigation, .inspector { display: none; }
  .navigation.phone-open, .inspector.phone-open { display: block; flex: none; }
  .workspace, .navigation, .inspector-content { overflow: visible; }
  .workspace { flex: 1 0 auto; }
  .inspector-adjustment { display: none; }
  .inspector { border-inline-start: 0; border-block-start: 1px solid currentColor; }
}
